insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p168', 'allemand', '3AS', 17, 168, 'L8 3AS p168 — Zum Hören : Der ideale Lehrer (Eigenschaften + Jan/Lars/Susanne/Miriam)', E'Zum Hören\nDer ideale Lehrer\n1. Wie stellen Sie sich den idealen Lehrer vor ? Kreuzen Sie die 3 Eigenschaften an, die Sie am wichtigsten finden :\nEr müsste die Schüler als gleichwertige Menschen behandeln.\nEr sollte sich durchsetzen können.\nEr sollte auf die Probleme der Schüler eingehen können.\nEr sollte vertrauenswürdig sein.\nEr sollte streng, aber gerecht sein.\nEr sollte mit der Klasse über aktuelle Themen diskutieren.\n2. Welche anderen Eigenschaften fallen Ihnen ein ?\n3. Hören Sie die folgenden Aussagen zu. Wie Stellen sich deutsche Schüler den idealen Lehrer vor ?\nJan aus Grünstadt : Der ideale Lehrer sollte hervorragend erklären können, sollte ein gutes Verhältnis zu seinen Schülern haben, vertrauenswürdig sein und einen lockeren Unterricht machen – auch mal Späße machen und die Späße der Schüler verstehen.\nLars aus Meckenheim : Ja, der ideale Lehrer sollte vor allem nett sein, dann sollte er vielleicht auch mal mit der Klasse über ein aktuelles Thema diskutieren, also auch über Sachen, die jetzt noch nicht zum Unterrichtsplan gehören, z.B. aktuelle politische Themen wie die Schulpolitik in Nordrhein-Westfalen….\nSusanne aus Aachen : Es gibt keinen idealen Lehrer, gute Lehrer ja, aber nicht ideal. Das gibt''s nicht!\nMiriam aus Bad Kissingen : Also, ideale Lehrer müssen Humor haben, sie sollten aber auch ernsthaft mit den Schülern reden können, sie sollten sich auch durchsetzen können, sollten …', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p169', 'allemand', '3AS', 17, 169, 'L8 3AS p169 — Der ideale Lehrer (suite) : Miriam Ende + Gordian + Florian + Sandra + Frage 4', E'… aber auch ruhig mal für einen Spaß zu haben sein und auch nicht allzu sauer werden, wenn die Schüler mal einen Streich spielen oder so..\nGordian aus Bad Homburg : Also, er muss freundlich sein, er soll eingehen, auch auf Probleme, und er soll auch guten Unterricht machen, wo man was lernt und es Spaß macht, zu lernen.\nSein Zwillingsbruder Florian : Ja, der müsste eigentlich sehr freundlich sein, dürfte nicht allzu viele Hausaufgaben aufgeben, und er müsste auch die Schüler als gleichwertige Menschen behandeln und nicht versuchen, sie fertig zu machen und unter Druck zu setzen.\nUnd schließlich Sandra aus Berlin : Ja, eigentlich streng, aber auch gerecht.\n4. Außer Sandra nennen alle Schüler mehr als eine Eigenschaft für einen idealen Lehrer. Welche Schülerin hat keine Vorstellung vom idealen Lehrer ? Warum ?', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p170', 'allemand', '3AS', 17, 170, 'L8 3AS p170 — Zum Schreiben : eigener Lebenslauf (Muster Reinert Wändel) + Traumberuf-Zeilen', E'Zum Schreiben\n1. Schreiben Sie Ihren eigenen Lebenslauf nach dem folgenden Muster.\nLebenslauf : Reinert Wändel\nName : Wändel\nVorname : Reinert\nGeboren : am 07. 08. 1978 in Marburg an der Lahn\n02. 09. 1984 : Grundschule in Marburg\n25. 06. 1988\n01. 09. 1988 : Goethe-Gymnasium in Frankfurt\n30. 06. 1991\n05. 09. 1991 : Schiller - Realschule in Frankfurt\n26. 06. 1994 : Realschulabschluss\n08. 10. 1994 : Übersetzer - Hochschule in Berlin\n03. 06. 1998 : (Französisch - Englisch)\n12. 09. 1998 : Praktikum in Frankreich\n30. 06. 1999\n15. 09. 2000 : Übersetzer bei einer internationalen Firma\n25. 05. 2006\n2. Schreiben Sie ein paar Zeilen über Ihren Traumberuf. (Begründen Sie Ihre Wahl.)', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p171', 'allemand', '3AS', 17, 171, 'L8 3AS p171 — Informationen : Jugend in Arbeit plus (NRW 2007) + 1LIVE Lehrstellenaktion', E'Informationen\nJugend in Arbeit plus\n«Jugend in Arbeit plus» ermöglicht Jugendlichen und jungen Erwachsenen unter 25 Jahren, die sich auf dem Arbeitsmarkt besonders schwer tun und länger als ein halbes Jahr arbeitslos sind, den Einstieg oder Wiedereinstieg in das Berufsleben. Ziel ist es, Jugendliche in Betriebe zu vermitteln und ihnen so wertvolle Berufserfahrung zu verschaffen.\nDie Jugendlichen werden von einer Beraterin oder einem Berater individuell unterstützt und bei der Beschäftigungsaufnahme begleitet. Bei Bedarf können die Jugendlichen an einer berufsbegleitenden Qualifizierung teilnehmen, um ihre Beschäftigungschancen zu verbessern. Die aufnehmenden Betriebe werden von den Fachkräften der Kammern begleitet und erhalten ein Jahr lang einen Lohnkostenzuschuss von 50 Prozent.\nBis zu 5.000 junge Menschen aus NRW können im Jahr 2007 über die Initiative Unterstützung finden. Gefördert wird das Programm aus Landes - und ESF - Mitteln.\nLogo : JA — Jugend In Arbeit plus · Banner : 1LIVE Lehrstellenaktion (WDR 2)', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p172', 'allemand', '3AS', 17, 172, 'L8 3AS p172 — Wortschatz L8 (Substantive/Adjektive/Adverbien/Funktionswörter/Verben)', E'Wortschatz\nSubstantive : der Abschluss · die Arbeitslosigkeit · die Arbeitswelt · der/die Ausstehende · der Bedarf an D. · der Berater · die Beraterin · die Bewerbung · die Bewertung · das Erlebnis · der Fußballprofi · das Gehalt · der Informationsvermittler · der Informatiker · die Kammer · die Kenntnis · die Lehrstelle · das Netzwerk · die Notaufnahme · der Mediengestalter · das Punktspiel · der Rundgang · die Schwierigkeit · der Sozialraum · die Steuerung · der Streetworker · die Streetworkerin · das Team · die Unterlagen · die Voraussetzung · der Werbegestalter\nAdjektive : gezielt · offene · selbständig · selber\nAdverbien : unterwegs · vorhin · vorzugsweise\nFunktionswörter : falls · soweit\nVerben : an/greifen · an/richten · an/vertrauen · an/labern · auf/nehmen · sich bedienen · drehen · entlohnen · entstehen · sich erneuern · sich erwähnen · hin/gehen · landen · reichen · schlendern · schminken · sperren · starten · unterstützen · verlangen · verteilen auf', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
